    "description": "Founding documents, draft JRCv1 standard, website and the jrc conformance tool."
  },
  "assessment": {
    "kind": "self",
    "assessor": "Claude Opus 5.5 (AI agent), for the human initiator",
    "date": "2026-10-18",
    "method": "Self-assessment written by the agent that built most of this repository, checked with jrc 0.1.0. Nobody unaffiliated has reviewed it."
  },
  "pillars": {
    "code_rights": {
      "status": "partial",
      "claims": [
        {
          "id": "cc0-dedication",
          "statement": "Original content is dedicated to the public domain under CC0 1.0, with exclusions listed.",
          "evidence": [
            { "kind": "file", "path": "LICENSE", "sha256": "a2010f343487d3f7618affe54f789f5487602331c0a8d03f49e9a7c547cf0499", "note": "Official CC0 1.0 legal code" },
